/* Commit 25.15 -- "Fabrigray Cotización Comercial" Print Format.
   Print-safe CSS: table-based layout only (no CSS grid, no flexbox, no
   position:fixed, no vh/vw, no JS) -- wkhtmltopdf compatibility takes
   priority over matching the reference pixel-for-pixel (section 25/3).
   Every selector is scoped under .fg-pdf -- never a bare table/td/tr/
   svg/img/h1 selector that could leak into another print format sharing
   the same print/PDF stylesheet. */

.fg-pdf {
	font-family: "Helvetica Neue", Arial, sans-serif;
	color: #1c2b39;
	font-size: 9.5pt;
	line-height: 1.35;
}

.fg-pdf table {
	width: 100%;
	border-collapse: collapse;
}

/* ---------- Header ---------- */

.fg-pdf-header-table {
	margin-bottom: 10px;
}

.fg-pdf-header-logo-cell {
	width: 90px;
	vertical-align: middle;
}

.fg-pdf-logo img {
	max-width: 80px;
	max-height: 80px;
}

.fg-pdf-logo-placeholder {
	width: 74px;
	height: 74px;
	border-radius: 50%;
	background: #2f7fc2;
	color: #ffffff;
	font-weight: bold;
	font-size: 11pt;
	text-align: center;
	line-height: 1.15;
	padding-top: 20px;
}

.fg-pdf-header-brand-cell {
	vertical-align: middle;
	text-align: center;
	padding: 0 12px;
}

.fg-pdf-brand-name {
	color: #0d3b66;
	font-size: 22pt;
	font-weight: bold;
	letter-spacing: 0.5px;
}

.fg-pdf-brand-tagline {
	color: #2f7fc2;
	font-size: 8.5pt;
	font-style: italic;
	margin-top: 3px;
}

.fg-pdf-header-card-cell {
	width: 160px;
	vertical-align: top;
}

.fg-pdf-quote-card {
	background: #0d3b66;
	color: #ffffff;
	border-radius: 6px;
	padding: 8px 12px;
	text-align: center;
}

.fg-pdf-quote-card-label {
	font-size: 9pt;
	font-weight: bold;
	letter-spacing: 1px;
}

.fg-pdf-quote-card-number {
	font-size: 16pt;
	font-weight: bold;
	margin-top: 2px;
}

.fg-pdf-quote-card-date {
	font-size: 8pt;
	margin-top: 4px;
	opacity: 0.92;
}

/* ---------- Intro ---------- */

.fg-pdf-intro {
	text-align: center;
	color: #2f7fc2;
	font-style: italic;
	font-size: 8.5pt;
	margin-bottom: 10px;
}

/* ---------- Client info box ---------- */

.fg-pdf-client-table {
	background: #eaf4fb;
	border-radius: 6px;
	margin-bottom: 10px;
}

.fg-pdf-client-cell {
	padding: 7px 10px;
	vertical-align: top;
	width: 25%;
}

.fg-pdf-icon {
	width: 14px;
	height: 14px;
	color: #2f7fc2;
	vertical-align: top;
	margin-right: 5px;
}

.fg-pdf-client-text {
	display: inline;
}

.fg-pdf-client-label {
	display: block;
	font-size: 7pt;
	font-weight: bold;
	color: #5c7791;
	letter-spacing: 0.4px;
}

.fg-pdf-client-value {
	display: block;
	font-size: 8.5pt;
	font-weight: bold;
	color: #1c2b39;
}

/* ---------- Items table ---------- */

.fg-pdf-items {
	margin-bottom: 10px;
}

.fg-pdf-items thead {
	display: table-header-group;
}

.fg-pdf-items tbody tr {
	page-break-inside: avoid;
}

.fg-pdf-items th {
	background: #0d3b66;
	color: #ffffff;
	font-size: 7.5pt;
	font-weight: bold;
	padding: 6px 5px;
	text-align: center;
	letter-spacing: 0.3px;
}

.fg-pdf-items td {
	padding: 5px;
	border-bottom: 1px solid #e2e8ee;
	font-size: 8.5pt;
	text-align: center;
	vertical-align: middle;
}

.fg-pdf-items tbody tr:nth-child(even) td {
	background: #f5f9fc;
}

.fg-pdf-col-desc {
	text-align: left !important;
}

.fg-pdf-col-num {
	text-align: right !important;
}

.fg-pdf-item-code {
	font-size: 6.5pt;
	color: #8496a6;
	margin-top: 1px;
}

/* ---------- Bottom section: validity + totals ---------- */

.fg-pdf-bottom-table {
	margin-bottom: 12px;
}

.fg-pdf-bottom-left-cell {
	width: 55%;
	vertical-align: top;
	padding-right: 10px;
}

.fg-pdf-bottom-right-cell {
	width: 45%;
	vertical-align: top;
}

.fg-pdf-validity-box {
	background: #eaf4fb;
	border-radius: 6px;
	padding: 8px 10px;
}

.fg-pdf-icon-lg {
	width: 26px;
	height: 26px;
	color: #2f7fc2;
	float: left;
	margin-right: 8px;
}

.fg-pdf-validity-text {
	font-size: 8pt;
	overflow: hidden;
}

.fg-pdf-price-scheme {
	margin-top: 3px;
	color: #2f7fc2;
	font-weight: bold;
}

.fg-pdf-totals {
	background: #f5f9fc;
	border-radius: 6px;
	overflow: hidden;
}

.fg-pdf-totals td {
	padding: 5px 8px;
	font-size: 8.5pt;
}

.fg-pdf-totals-icon {
	width: 22px;
	color: #2f7fc2;
}

.fg-pdf-icon-sm {
	width: 12px;
	height: 12px;
	vertical-align: middle;
	color: #ffffff;
}

.fg-pdf-totals-icon .fg-pdf-icon-sm {
	color: #2f7fc2;
}

.fg-pdf-totals-label {
	text-align: left;
}

.fg-pdf-totals-value {
	text-align: right;
	font-weight: bold;
}

.fg-pdf-totals-grand {
	background: #0d3b66;
}

.fg-pdf-totals-grand td {
	color: #ffffff;
	font-weight: bold;
	font-size: 10pt;
	padding: 7px 8px;
}

/* ---------- Signature ---------- */

.fg-pdf-signature {
	margin-bottom: 14px;
}

.fg-pdf-signature-name {
	font-size: 13pt;
	font-style: italic;
	color: #0d3b66;
}

.fg-pdf-signature-line {
	border-top: 1px solid #8496a6;
	width: 200px;
	margin-top: 4px;
}

.fg-pdf-signature-title {
	font-size: 8pt;
	color: #5c7791;
	margin-top: 2px;
}

/* ---------- Decorative line ---------- */

.fg-pdf-decor {
	text-align: right;
	color: #a9c7de;
	font-style: italic;
	font-size: 9pt;
	margin-bottom: 8px;
}

/* ---------- Footer ---------- */

.fg-pdf-footer-table {
	background: #0d3b66;
	border-radius: 6px;
}

.fg-pdf-footer-cell {
	color: #ffffff;
	font-size: 8pt;
	padding: 8px 10px;
	text-align: center;
	width: 33.33%;
}

.fg-pdf-icon-sm-white {
	width: 11px;
	height: 11px;
	vertical-align: middle;
	margin-right: 4px;
	color: #ffffff;
}
